115	/**
116	 * Parses a numeric config field, enforcing integer-only values and optional
117	 * `[min, max]` range bounds.
118	 *
119	 * - If `value` is not a `number`, returns `defaultValue`.
120	 * - If `value` is a number but not an integer (e.g. a float like `220.5`),
121	 *   returns `defaultValue`.
122	 * - If `min` and `max` are provided and the integer value is outside that range,
123	 *   emits `console.warn` but returns the value as-is (no clamping).
124	 *
125	 * @param value     Raw value read from the config file.
126	 * @param fieldName Field name used in warning messages.
127	 * @param defaultValue Fallback value for non-numeric or float inputs.
128	 * @param min       Optional lower bound (inclusive).
129	 * @param max       Optional upper bound (inclusive).
130	 */
131	function parseIntegerField(
132	    value: unknown,
133	    fieldName: string,
134	    defaultValue: number,
135	    min?: number,
136	    max?: number,
137	): number {
138	    if (typeof value !== 'number') {
139	        return defaultValue;
140	    }
141	    if (!Number.isInteger(value)) {
142	        return defaultValue;
143	    }
144	    if (min !== undefined && max !== undefined && (value < min || value > max)) {
145	        console.warn(
146	            `Configuration warning: "${fieldName}" value ${value} is outside the allowed range ` +
147	            `[${min}, ${max}]. The value will be used as-is.`
148	        );
149	    }
150	    return value;
151	}
152	
153	/**
154	 * Validates and returns the `gitCredentials` value from the raw config,
155	 * auto-migrating the legacy `Record<string, string>` format to the new
156	 * `GitCredentialEntry[]` format when necessary.
157	 *
158	 * **Accepted inputs:**
159	 * - `undefined` / `null` → returns `undefined`
160	 * - `GitCredentialEntry[]` (new format) → validated and returned as-is
161	 * - `Record<string, string>` (old format, hostname→token map) → migrated to
162	 *   `GitCredentialEntry[]` with `id` derived from the hostname in kebab-case
163	 *   and `label` set to the hostname. Colliding IDs get a numeric suffix (`-2`,
164	 *   `-3`, …).
165	 * - An empty array `[]` → returns `[]`
166	 *
167	 * **Validation (new-format arrays):**
168	 * - Every entry must have non-empty `id`, `label`, `host`, and `token` fields.
169	 * - Duplicate `id` values within the array are rejected.
170	 *
171	 * @returns `undefined` when the field is absent or null; otherwise a
172	 *   `GitCredentialEntry[]` (possibly empty).
173	 * @throws {Error} If the value is present but structurally invalid, or if any
174	 *   entry fails validation.
175	 */
176	function parseGitCredentials(value: unknown): GitCredentialEntry[] | undefined {
177	    if (value === undefined || value === null) {
178	        return undefined;
179	    }
180	
181	    // --- New format: array of GitCredentialEntry objects ---
182	    if (Array.isArray(value)) {
183	        // Empty array is valid — treat as "no credentials".
184	        if (value.length === 0) {
185	            return [];
186	        }
187	
188	        const seenIds = new Set<string>();
189	
190	        for (let i = 0; i < value.length; i++) {
191	            const entry = value[i] as Record<string, unknown>;
192	
193	            if (typeof entry !== 'object' || entry === null || Array.isArray(entry)) {
194	                throw new Error(
195	                    `Configuration error: gitCredentials[${i}] must be a credential object, got ${typeof entry}.`
196	                );
197	            }
198	
199	            for (const field of ['id', 'label', 'host', 'token'] as const) {
200	                const fieldValue = entry[field];
201	                if (typeof fieldValue !== 'string' || fieldValue.trim() === '') {
202	                    throw new Error(
203	                        `Configuration error: gitCredentials[${i}].${field} must be a non-empty string.`
204	                    );
205	                }
206	            }
207	
208	            const id = (entry['id'] as string).trim();
209	            if (seenIds.has(id)) {
210	                throw new Error(
211	                    `Configuration error: gitCredentials contains duplicate id "${id}".`
212	                );
213	            }
214	            seenIds.add(id);
215	        }
216	
217	        return value as GitCredentialEntry[];
218	    }
219	
220	    // --- Old format: plain object mapping hostname → token ---
221	    if (typeof value === 'object') {
222	        const legacyMap = value as Record<string, unknown>;
223	        const entries = Object.entries(legacyMap);
224	
225	        // Empty legacy object → return undefined (no credentials configured).
226	        if (entries.length === 0) {
227	            return undefined;
228	        }
229	
230	        const result: GitCredentialEntry[] = [];
231	        const usedIds = new Set<string>();
232	
233	        for (const [host, token] of entries) {
234	            if (typeof token !== 'string') {
235	                throw new Error(
236	                    `Configuration error: gitCredentials["${host}"] must be a string, got ${typeof token}.`
237	                );
238	            }
239	            if (token === '') {
240	                throw new Error(
241	                    `Configuration error: gitCredentials["${host}"] must not be an empty string.`
242	                );
243	            }
244	
245	            // Derive a kebab-case ID from the hostname.
246	            const baseId = toKebabCase(host);
247	            let candidateId = baseId;
248	            let suffix = 2;
249	            while (usedIds.has(candidateId)) {
250	                candidateId = `${baseId}-${suffix}`;
251	                suffix++;
252	            }
253	            usedIds.add(candidateId);
254	
255	            result.push({
256	                id: candidateId,
257	                label: host,
258	                host,
259	                token,
260	            });
261	        }
262	
263	        return result;
264	    }
265	
266	    throw new Error(
267	        'Configuration error: "gitCredentials" must be an array of credential entries or omitted.'
268	    );
269	}
